extra_methods.body:
var data = new SaveSystemData();
data.ActId = _lastActId;
try {
	File.WriteAllText(_savePath, JsonUtility.ToJson(data));
} catch (Exception e) {
	Debug.LogError("Save failed: " + e.Message);
}

if (!File.Exists(_savePath)) return false;
try {
	var json = File.ReadAllText(_savePath);
	var data = JsonUtility.FromJson<SaveSystemData>(json);
	_lastActId = data.ActId;
	return true;
} catch (Exception e) {
	Debug.LogError("Load failed: " + e.Message);
}
return false;

input.awake_extra:
if (_oxygenSource == null) _oxygenSource = GetComponent<AudioSource>();
maxHealth = 100f;
startHealth = maxHealth;

extra_methods.body:
if (_engineSound != null) {
    float speedFactor = Mathf.Max(0f, _speed / 150f);
    float rainDampening = 1f - (_rainIntensity * 0.3f);
    _engineSound.volume = speedFactor * rainDampening;
    _engineSound.pitch = 0.8f + (speedFactor * 0.4f) + (_rainIntensity * 0.2f);
}

input.update_extra:
if (_target != null && _engageDistCount > 0) {
    float swarmAggression = ReadStat("swarm_aggression") * _swarmAggression;
    if (Random.value < swarmAggression) TryAttack(_engageDistSum);
}

// Maintain hover formation height relative to target
if (_target != null && transform.position.y > _target.position.y + _hoverAltitudeOffset) {
    transform.position += Vector3.up * Time.deltaTime * 2f;
} else if (transform.position.y < _target.position.y - _hoverAltitudeOffset) {
    transform.position += Vector3.down * Time.deltaTime * 2f;
}

extra_methods.body:
GameObject enemy = Instantiate(_enemyPrefab, ResolveSpawnPosition(), Quaternion.identity);
if (enemy != null) {
    enemy.AddComponent<AIController>();
    _alive.Add(enemy);
}
OnDespawned?.Invoke(null);

if (ps == null) return;
ParticleSystem.MainModule main = ps.main;
ParticleSystem.EmissionModule emission = ps.emission;
ParticleSystem.MinMaxCurve startSizeCurve = main.startSize;

// Adjust size based on rain intensity
startSizeCurve.minValue *= _rainIntensity;
startSizeCurve.maxValue *= _rainIntensity;
main.startSize = startSizeCurve;

// Apply neon color to particles
Color32[] colorsOverLifetime = ps.colorOverLifetime.colors;
for (int i = 0; i < colorsOverLifetime.Length; i++)
{
    colorsOverLifetime[i] = _neonColor;
}
ps.colorOverLifetime.SetColors(_neonColor, _neonColor);

// Disable alpha source in emission if needed for solid neon look
emission.useAlphaSource = false;
}
